using System;
using LastRail.Run;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public sealed class BTravelCommandTests {
  static JObject Command(string kind="RECOVER")=>new JObject{["version"]="combat.b-travel-command.v1.20261031",["requestId"]="request",["destinationEventId"]="destination",["nodeId"]="node",["mapRevision"]=2,["expectedRevision"]=0,["kind"]=kind};
  static JObject Receipt()=>new JObject{["version"]="combat.b-travel-command.v1.20261031",["requestId"]="request",["destinationEventId"]="destination",["nodeId"]="node",["mapRevision"]=2,["revision"]=1,["acceptedAtMs"]=1234,["state"]=new JObject{["tick"]=0,["distanceMm"]=0,["remainderUnits"]=0,["debtTicks"]=0,["paused"]=true,["throttleBps"]=10000}};
  [Test] public void RequestKeepsOriginalBodyAndAcceptsTwoHundredCharacterIds(){var p=Command();p["nodeId"]=new string('n',200);string body=p.ToString();var c=BTravelCommand.Read(body);Assert.AreEqual(body,c.BodyJson);Assert.AreEqual(200,c.NodeId.Length);}
  [TestCase(0)][TestCase(13001)] public void RejectsThrottleOutsideWireRange(int bps){var p=Command("TRAVEL_THROTTLE");p["bps"]=bps;Assert.Throws<ArgumentException>(()=>BTravelCommand.Read(p.ToString()));}
  [Test] public void RejectsClientElapsedAndNumericPause(){var p=Command();p["elapsed"]=1;Assert.Throws<ArgumentException>(()=>BTravelCommand.Read(p.ToString()));p=Command("PAUSE");p["value"]=1;Assert.Throws<ArgumentException>(()=>BTravelCommand.Read(p.ToString()));}
  [Test] public void AcceptedStateIsServerStateAndCaptureDoesNotMutateIt(){var p=Receipt();p["state"]["distanceMm"]=345;var r=BTravelReceipt.Read(p.ToString(),BTravelCommand.Read(Command().ToString()));r.Capture()["state"]["distanceMm"]=999;Assert.AreEqual(345,r.State.DistanceMm);Assert.AreEqual(1,r.Revision);}
  [TestCase("requestId")][TestCase("destinationEventId")][TestCase("nodeId")] public void RejectsReceiptDifferentContext(string key){var p=Receipt();p[key]="other";Assert.Throws<ArgumentException>(()=>BTravelReceipt.Read(p.ToString(),BTravelCommand.Read(Command().ToString())));}
  [Test] public void RejectsWrongRevisionAndDistanceRemainder(){var p=Receipt();p["revision"]=2;Assert.Throws<ArgumentException>(()=>BTravelReceipt.Read(p.ToString(),BTravelCommand.Read(Command().ToString())));p=Receipt();p["state"]["remainderUnits"]=100000000000L;Assert.Throws<ArgumentException>(()=>BTravelReceipt.Read(p.ToString(),BTravelCommand.Read(Command().ToString())));}
  [Test] public void InitialRequiresConfirmIdentityAndRevisionZero(){var p=Receipt();p["requestId"]="destination";p["revision"]=0;p["state"]["paused"]=false;Assert.AreEqual(0,BTravelReceipt.ReadInitial(p.ToString(),"destination","node",2).Revision);p["revision"]=1;Assert.Throws<ArgumentException>(()=>BTravelReceipt.ReadInitial(p.ToString(),"destination","node",2));}
  [Test] public void CurrentMapIsRecoveryOnlyAndDoesNotCreateTravelState(){var p=new JObject{["version"]="combat.b-travel-command.v1.20261031",["requestId"]="request",["status"]="CURRENT_MAP",["runStatus"]="ACTIVE",["mapRevision"]=3,["mapState"]=new JObject{["version"]="operation.map-progress.v1",["traversedEdgeIds"]=new JArray("edge"),["pendingEdgeId"]=null,["phase"]="ACTIVE",["holdIds"]=new JArray()},["mapReceipt"]=null};var r=BTravelReceipt.Read(p.ToString(),BTravelCommand.Read(Command().ToString()));Assert.IsTrue(r.IsCurrentMap);Assert.IsNull(r.State);Assert.IsNull(r.MapReceipt);Assert.Throws<ArgumentException>(()=>BTravelReceipt.Read(p.ToString(),BTravelCommand.Read(Command("ARRIVE").ToString())));}
  [Test] public void ConflictKeepsLatestOriginalRequestIdentityAndDoesNotBecomeSuccess(){var receipt=Receipt();receipt["requestId"]="earlier-accepted";receipt["revision"]=3;var p=new JObject{["accepted"]=false,["errorCode"]="combat_b_travel_revision_conflict",["current"]=receipt};var r=BTravelReceipt.ReadConflictCurrent(p.ToString(),BTravelCommand.Read(Command().ToString()));Assert.AreEqual("earlier-accepted",r.RequestId);Assert.AreEqual(3,r.Revision);p["accepted"]=true;Assert.Throws<ArgumentException>(()=>BTravelReceipt.ReadConflictCurrent(p.ToString(),BTravelCommand.Read(Command().ToString())));}
  [Test] public void DestinationPreservesOptionalInitialWithoutGuessingMissingState(){var intent=new BOperationDestinationIntent("account","run","confirm",1,"edge");var p=new JObject{["version"]="operation.map-destination.v1",["requestId"]="confirm",["revision"]=2,["phase"]="TRAVELLING",["pendingEdgeId"]="edge"};Assert.IsNull(BOperationDestinationReceipt.Read(p.ToString(),intent).TravelInitial);var initial=Receipt();initial["requestId"]="confirm";initial["destinationEventId"]="confirm";initial["revision"]=0;initial["state"]["paused"]=false;p["travelInitial"]=initial;var r=BOperationDestinationReceipt.Read(p.ToString(),intent);r.TravelInitial["revision"]=99;Assert.AreEqual(0,(long)r.TravelInitial["revision"]);}
  static JObject Arrived(){var p=Receipt();p["state"]["tick"]=4;p["state"]["paused"]=false;string hash=new string('a',64);p["arrival"]=new JObject{["version"]="combat.b-arrival-report.v2.20261020",["evidenceRef"]="B_ARRIVAL:proof",["requestId"]="request",["arrivalAccepted"]=true,["progressAuthorized"]=true,["combatTruth"]="NOT_PROVEN",["verificationLevel"]="ORIGINAL_PINNED_TRAVEL_COMMAND_REPLAY",["missingSources"]=new JArray(),["observation"]=new JObject{["version"]="combat.b-boundary-arrival-observation.v1.20261020",["accountId"]="account",["runId"]="run",["nodeId"]="node",["mapRevision"]=2,["nativeContextId"]="native",["departurePinHash"]=hash,["nodeSourceHash"]=hash,["operationBindingHash"]=hash,["evidenceRef"]="B_ARRIVAL:proof",["originalEventId"]="arrival",["sequence"]=3,["sourceRevision"]=3,["checkpointHash"]="sha256:"+hash,["destination"]=new JObject{["eventId"]="destination",["mapRevision"]=2,["receiptHash"]=hash,["edgeId"]="edge"},["arrival"]=new JObject{["eventId"]="arrival",["sequence"]=3,["tick"]=4},["travelStopped"]=true,["combatTruth"]="NOT_PROVEN"}};return p;}
  [Test] public void ArrivalExposesEvidenceOnlyForMatchingRequestAndAuthenticatedScope(){var p=Arrived();var request=BTravelCommand.Read(Command("ARRIVE").ToString());var r=BTravelReceipt.Read(p.ToString(),request);r.RequireScope("account","run");Assert.AreEqual("B_ARRIVAL:proof",r.ArrivalEvidenceRef);Assert.Throws<ArgumentException>(()=>r.RequireScope("other","run"));p["arrival"]["observation"]["destination"]["eventId"]="other";Assert.Throws<ArgumentException>(()=>BTravelReceipt.Read(p.ToString(),request));}
  [Test] public void PauseAtBoundaryRetainsPauseIntentAndValidatedArrivalWithoutRewritingServerState(){var p=Arrived();p["pauseIntent"]=true;var command=Command("PAUSE");command["value"]=true;var r=BTravelReceipt.Read(p.ToString(),BTravelCommand.Read(command.ToString()));Assert.IsTrue(r.PauseIntent);Assert.IsFalse(r.State.Paused);Assert.AreEqual("B_ARRIVAL:proof",r.ArrivalEvidenceRef);r.Capture()["pauseIntent"]=false;Assert.IsTrue(r.PauseIntent);}
  [Test] public void PauseArrivalRequiresTrueMarkerAndOriginalPauseIntent(){var p=Arrived();var command=Command("PAUSE");command["value"]=true;Assert.Throws<ArgumentException>(()=>BTravelReceipt.Read(p.ToString(),BTravelCommand.Read(command.ToString())));p["pauseIntent"]=false;Assert.Throws<ArgumentException>(()=>BTravelReceipt.Read(p.ToString(),BTravelCommand.Read(command.ToString())));p["pauseIntent"]=true;command["value"]=false;Assert.Throws<ArgumentException>(()=>BTravelReceipt.Read(p.ToString(),BTravelCommand.Read(command.ToString())));Assert.Throws<ArgumentException>(()=>BTravelReceipt.Read(p.ToString(),BTravelCommand.Read(Command("ARRIVE").ToString())));command["value"]=true;p.Remove("arrival");Assert.Throws<ArgumentException>(()=>BTravelReceipt.Read(p.ToString(),BTravelCommand.Read(command.ToString())));}
  [Test] public void ConflictPreservesStoredPauseMarkerWithoutInventingArrivalEvidence(){var current=Receipt();current["requestId"]="accepted-pause";current["state"]["paused"]=false;current["pauseIntent"]=true;var p=new JObject{["accepted"]=false,["errorCode"]="combat_b_travel_revision_conflict",["current"]=current};var r=BTravelReceipt.ReadConflictCurrent(p.ToString(),BTravelCommand.Read(Command().ToString()));Assert.IsTrue(r.PauseIntent);Assert.IsNull(r.ArrivalEvidenceRef);}
  [Test] public void ArriveCannotSucceedWithoutArrivalEvidence(){var p=Receipt();p["state"]["paused"]=false;Assert.Throws<ArgumentException>(()=>BTravelReceipt.Read(p.ToString(),BTravelCommand.Read(Command("ARRIVE").ToString())));}
 }
}
